<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();
$kind=(string)($_GET['kind']??'helpdesk');if(!in_array($kind,['clearance','helpdesk','form'],true)){http_response_code(404);exit;}
$labels=['clearance'=>'Digital clearance','helpdesk'=>'School helpdesk','form'=>'School forms'];$error='';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST')try{
    if(($_POST['action']??'')==='create')$id=work_create($kind,$_POST);else work_update($id,$_POST);
    set_flash('success','Your request was updated.');redirect('workflows.php?kind='.$kind.'&id='.$id);
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$request=$id?work_request($id):null;if($id&&(!$request||$request['kind']!==$kind)){http_response_code(404);exit('Request not found.');}
$offices=rows('SELECT * FROM campus_offices WHERE active=1 ORDER BY name');$types=rows('SELECT * FROM campus_form_types WHERE active=1 ORDER BY name');$u=current_user();$owner=$request&&(int)$request['owner_id']===(int)$u['id'];
render_header($labels[$kind]); ?>
<div class="page-title"><div><span class="eyebrow">CONNECTED CAMPUS</span><h1><?= e($labels[$kind]) ?></h1><p><?= e(['clearance'=>'Review your clearance with each school office.','helpdesk'=>'Send a concern to the right office and follow its response.','form'=>'Submit a school form and track its approval route.'][$kind]) ?></p></div><a class="btn btn-outline-primary" href="workflows.php?kind=<?= e($kind) ?>">All requests</a></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if($request):$steps=work_steps($id); ?>
<section class="panel"><div class="page-title"><div><span class="eyebrow"><?= e($request['reference']) ?></span><h2><?= e($request['title']) ?></h2><p><?= e($request['status']) ?> · Updated <?= e(campus_time($request['updated_at'])) ?></p></div><?php if($request['status']==='Approved'&&$kind==='clearance'): ?><button class="btn btn-outline-primary no-print" type="button" onclick="window.print()">Print clearance summary</button><?php endif; ?></div><p class="campus-preserve"><?= e($request['details']) ?></p><p class="small text-muted">This workflow records office decisions. It does not calculate official balances, take payments, or issue academic documents.</p></section>
<div class="row g-4"><div class="col-lg-7"><section class="panel"><h2>Office progress</h2><?php foreach($steps as $step): ?><article class="campus-step"><h3><?= e($step['office_name']) ?></h3><span class="badge-soft"><?= e($step['status']) ?></span><p><?= e($step['note']) ?></p><?php if($step['reviewed_at']): ?><small>Reviewed <?= e(campus_time($step['reviewed_at'])) ?></small><?php endif; ?>
<?php if(!$owner&&can_review_step($step)&&$step['status']==='Pending'&&!in_array($request['status'],['Approved','Resolved','Rejected','Cancelled'],true)): ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="review"><input type="hidden" name="revision" value="<?= (int)$request['revision'] ?>"><input type="hidden" name="step_id" value="<?= (int)$step['id'] ?>"><label for="decision-<?= (int)$step['id'] ?>">Office decision</label><select id="decision-<?= (int)$step['id'] ?>" name="decision" class="form-select" required><option value="">Choose decision</option><option value="Approved"><?= $kind==='helpdesk'?'Resolve concern':'Approve office step' ?></option><option value="Returned">Return for more information</option><option value="Rejected">Reject request</option></select><label for="note-<?= (int)$step['id'] ?>">Reason / instructions for requester</label><textarea id="note-<?= (int)$step['id'] ?>" name="note" rows="3" maxlength="2000" class="form-control"></textarea><button class="btn btn-primary">Save decision</button></form><?php endif; ?></article><?php endforeach; ?></section></div>
<div class="col-lg-5"><section class="panel"><h2>Conversation & history</h2><?php foreach(rows('SELECT e.*,u.full_name FROM campus_work_events e JOIN users u ON u.id=e.actor_id WHERE request_id=? '.($owner?'AND internal=0':'').' ORDER BY e.id',[$id]) as $event): ?><article class="campus-event"><strong><?= e($event['full_name']) ?><?= $event['internal']?' · Staff note':'' ?></strong><p class="campus-preserve"><?= e($event['body']) ?></p><small><?= e(campus_time($event['created_at'])) ?></small></article><?php endforeach; ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="message"><input type="hidden" name="revision" value="<?= (int)$request['revision'] ?>"><label for="reply">Reply</label><textarea id="reply" name="note" minlength="2" maxlength="2000" rows="3" class="form-control" required></textarea><?php if(!$owner): ?><label><input type="checkbox" name="internal" value="1"> Internal staff note (not shown to requester)</label><?php endif; ?><button class="btn btn-outline-primary">Send reply</button></form></section>
<?php if($owner&&$request['status']==='Returned'): ?><section class="panel"><h2>Resubmit your request</h2><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="resubmit"><input type="hidden" name="revision" value="<?= (int)$request['revision'] ?>"><label for="corrected-details">Corrected request details</label><textarea id="corrected-details" name="details" minlength="5" maxlength="3000" rows="4" class="form-control" required><?= e($request['details']) ?></textarea><label for="correction">What did you correct or provide?</label><textarea id="correction" name="note" minlength="5" maxlength="2000" rows="3" class="form-control" required></textarea><button class="btn btn-primary">Resubmit for review</button></form></section><?php endif; ?>
<?php if($owner&&!in_array($request['status'],['Approved','Resolved','Rejected','Cancelled'],true)): ?><form method="post" class="panel no-print"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="revision" value="<?= (int)$request['revision'] ?>"><p>Cancelling closes this request. Office decisions remain in its history.</p><button class="btn btn-outline-danger">Cancel request</button></form><?php endif; ?></div></div>
<?php else:$requests=rows('SELECT r.* FROM campus_requests r WHERE r.kind=? AND '.work_scope().' ORDER BY r.updated_at DESC,r.id DESC LIMIT 100',[$kind]); ?>
<div class="row g-4"><div class="col-lg-5"><section class="panel"><h2>Start a request</h2><?php if($kind!=='helpdesk'&&$u['role']!=='Student'): ?><p>Clearance and school forms are submitted by students. Assigned office reviewers see their requests alongside.</p><?php else: ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="create"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><?php if($kind==='helpdesk'): ?><label for="office_id">School office</label><select id="office_id" name="office_id" class="form-select" required><option value="">Choose office</option><?php foreach($offices as $office): ?><option value="<?= (int)$office['id'] ?>"><?= e($office['name']) ?></option><?php endforeach; ?></select><label for="work-title">Concern title</label><input id="work-title" name="title" minlength="3" maxlength="120" class="form-control" required><?php elseif($kind==='form'): ?><label for="form_type">School form</label><select id="form_type" name="form_type" class="form-select" required><option value="">Choose form</option><?php foreach($types as $type): ?><option value="<?= (int)$type['id'] ?>"><?= e($type['name']) ?></option><?php endforeach; ?></select><?php else: ?><p>Clearance follows the active school year and the school's configured offices. One active request per school year.</p><?php endif; ?><label for="work-details">Details / purpose</label><textarea id="work-details" name="details" minlength="5" maxlength="3000" rows="5" class="form-control" required></textarea><small>Do not include passwords, bank information, or sensitive identity documents in messages.</small><button class="btn btn-primary">Submit request</button></form><?php endif; ?></section></div><div class="col-lg-7"><section class="panel"><h2>Your workspace</h2><?php if(!$requests)empty_state('No requests yet','Your submissions and assigned office requests will appear here.');foreach($requests as $r): ?><article class="campus-event"><strong><?= e($r['title']) ?></strong><p><?= e($r['reference'].' · '.$r['status']) ?></p><a class="btn btn-sm btn-outline-primary" href="?kind=<?= e($kind) ?>&id=<?= (int)$r['id'] ?>">Open request</a></article><?php endforeach; ?></section></div></div><?php endif;render_footer(); ?>
